board Divider {
    use library "tiny";
    component R1: RESISTOR { value = 10kohm; }
    component R2: RESISTOR { value = 10kohm; }
    net VIN { R1.1; }
    net MID { R1.2; R2.1; }
    net GND { R2.2; }
    supply VIN { voltage = 3.3V; external = true; }
    supply GND { voltage = 0V; external = true; }
}
